#!/usr/bin/env bash
# default-trusted-bots.sh — single source of truth for app-bot logins that
# are ALWAYS trusted by the reusable workflows' actor gates (job-level skip,
# pre-flight author check, trusted-bot-auth TOKEN bypass).
#
# ai-workflows-propagation[bot]: THIS pipeline's own propagation bot — it is
# authenticated by the AI_WORKFLOWS_APP_ID/AI_WORKFLOWS_APP_PRIVATE_KEY
# secrets held here and authors every consumer sync PR and dogfood-bump PR
# generated by propagate.yml. Consumers pin this repo's workflows to receive
# those syncs, so the bot is trusted by construction; requiring each
# consumer to also hand-wire it into trusted_app_bots reproduced the exact
# chicken-and-egg the input exists to end (each new consumer's FIRST sync PR
# — the one carrying their wiring — was refused as its author). Each entry
# is still an exact login; never wildcards, never human accounts. Consumers
# extend (not replace) this set via their caller's trusted_app_bots input.
#
# Sourced by scripts/trusted-bot-auth.sh and scripts/author-permission.sh —
# keep it assignments-only (no shell builtin state changes, no output).

DEFAULT_TRUSTED_APP_BOTS='["ai-workflows-propagation[bot]"]'
